// SettingsRequest Replaces the signed-in user's saved GitHub/Forgejo configuration.
// A blank `githubToken` or `forgejoToken` keeps whatever token is
// already saved for that forge rather than clearing it — this is
// the only way to update the username fields without having to
// resubmit a token you don't want to re-paste. githubAppInstallationId
// is different: a plain replace like githubUsername, not coalesced —
// 0 or omitted really does disconnect the App. Rejected (400) if
// the server has no GitHub App configured (see
// SettingsResponse.githubAppConfigured). Theme isn't settable
// here at all — see PUT /api/settings/theme.
type SettingsRequest struct {
	ForgejoToken *string `json:"forgejoToken,omitempty"`

	// ForgejoUrl Required, once the save is merged with what is already stored,
	// whenever a Forgejo token or username is set. That depends on
	// stored state, so a schema alone can't express it: a save that
	// breaks it is a 400 naming `forgejoUrl`.
	//
	// Must be a plain `http://` or `https://` base URL with a host,
	// optionally with a path prefix. One that carries a username,
	// password, query string or fragment, or has another scheme, is a
	// 400 naming `forgejoUrl`, and nothing is saved. The error never
	// repeats the URL.
	ForgejoUrl      *string `json:"forgejoUrl,omitempty"`
	ForgejoUsername *string `json:"forgejoUsername,omitempty"`

	// GithubAppInstallationId 0 means none. A negative or non-integer value is a 400 naming
	// this field, as is any value on a server with no GitHub App
	// configured.
	GithubAppInstallationId *int64  `json:"githubAppInstallationId,omitempty"`
	GithubToken             *string `json:"githubToken,omitempty"`
	GithubUsername          *string `json:"githubUsername,omitempty"`

	// HideDependencyDashboard Replaces the saved choice; omitted means false, like
	// `renovateAuthors`, so a form sends it on every save. See
	// SettingsResponse.hideDependencyDashboard.
	HideDependencyDashboard *bool `json:"hideDependencyDashboard,omitempty"`

	// IgnoredTitles Replaces the saved list; omitted or empty clears it. Entries are
	// trimmed; blanks and repeats (ignoring case) are dropped. Each
	// must compile as a Go RE2 regular expression: one that does not
	// is a 400 naming `ignoredTitles` and the entry, with the reason in
	// plain words ("ignoredTitles entry 2, "(": missing closing )"),
	// and nothing is saved. More than 20 entries, or an entry over 200
	// characters, is a 400 too. See SettingsResponse.ignoredTitles.
	IgnoredTitles *[]string `json:"ignoredTitles,omitempty"`

	// RenovateAuthors Replaces the saved list. Entries are trimmed; blanks and
	// repeats (ignoring case) are dropped. Omitted or empty clears it.
	RenovateAuthors     *[]string `json:"renovateAuthors,omitempty"`
	RenovateRebaseLabel *string   `json:"renovateRebaseLabel,omitempty"`
}

// SettingsResponse The signed-in user's own GitHub/Forgejo configuration. Never
// includes a forge token's value — only whether one is currently
// saved, so the UI can show a "Configured" badge without the secret
// ever reaching the browser. webhookToken/webhookSecret are the
// exception: they're ours to hand back in the clear, since the user
// has to paste them into the forge's own webhook setup.
type SettingsResponse struct {
	// ForgejoTokenSet Whether a Forgejo token is currently saved.
	ForgejoTokenSet bool `json:"forgejoTokenSet"`

	// ForgejoUrl Always without a username, password, query string or fragment,
	// even if the stored value predates those being refused.
	ForgejoUrl string `json:"forgejoUrl"`

	// ForgejoUsername Used as a token-free public-repos fallback when no Forgejo token is set.
	ForgejoUsername string `json:"forgejoUsername"`

	// GithubAppConfigured Whether this server has a GitHub App configured at all
	// (server-wide GITHUB_APP_ID/GITHUB_APP_PRIVATE_KEY_BASE64 —
	// not a per-user setting). The Settings page uses this to
	// explain why githubAppInstallationId can't be saved when
	// it's false.
	GithubAppConfigured bool `json:"githubAppConfigured"`

	// GithubAppInstallationId The installation ID of the alrayyes-automation GitHub App
	// this user has connected, or 0 if none. Not a
	// secret — it's an opaque integer GitHub already shows the
	// user on its own installation settings page — so, unlike
	// githubTokenSet, this round-trips as a plain value. Takes
	// precedence over a saved githubToken whenever both are set
	// and the server has an App configured (see
	// githubAppConfigured).
	GithubAppInstallationId int64 `json:"githubAppInstallationId"`

	// GithubTokenSet Whether a GitHub token is currently saved.
	GithubTokenSet bool `json:"githubTokenSet"`

	// GithubUsername Used as a token-free public-repos fallback when no GitHub token is set.
	GithubUsername string `json:"githubUsername"`

	// HideDependencyDashboard Whether the user hides the bot-kept "Dependency Dashboard" issue
	// everywhere: the server leaves a `housekeeping` issue out of the
	// `issues` of GET /api/dashboard and its stream, and out of every
	// count and total built from them (`navCounts`, Insights). Always
	// present once the server applies it.
	HideDependencyDashboard *bool `json:"hideDependencyDashboard,omitempty"`

	// IgnoredTitleCounts Per pattern in `ignoredTitles`, same order and same length: how
	// many of the viewer's currently open issues that pattern matches
	// on its own. An issue two patterns match counts for both, so the
	// entries can sum to more than `settingsHiddenIssueCount`. Every
	// entry is null while the count is unknown (the viewer's first
	// refresh has not finished, see `firstRefreshDone` on the
	// dashboard snapshot, or there is no snapshot), never a made-up 0.
	// Only this viewer's issues are counted. On GET and on the PUT
	// response alike: a PUT returns the counts for the list it just
	// saved, worked out from the issues the viewer had before the save.
	IgnoredTitleCounts []*int `json:"ignoredTitleCounts"`

	// IgnoredTitles Patterns for issue titles to leave out, in the server's own
	// regular expression syntax (Go RE2: no lookahead and no
	// backreferences). A pattern matches anywhere in the title and
	// ignores case; an issue matching any one is left out of `issues`
	// and of every count and total built from them, the same as
	// `hideDependencyDashboard`. Always present once the server
	// applies it. Empty means none.
	IgnoredTitles *[]string `json:"ignoredTitles,omitempty"`

	// RenovateAuthors The logins that are Renovate on the user's forges. On GitHub the
	// App's own `renovate` and `renovate[bot]` are always recognised.
	// A Forgejo or GitLab instance has no App: Renovate runs there as
	// an ordinary account with whatever name the instance gave it, so
	// the user lists it here. A pull request by one of these gets
	// Renovate's own rebase, not Update branch, and is a `dependency`.
	// Matched case-insensitively. Empty means only the GitHub slugs.
	RenovateAuthors []string `json:"renovateAuthors"`

	// RenovateRebaseLabel The label Renovate's own rebase/retry trigger listens for on
	// a repo (Renovate's own `rebaseLabel` config option — genuinely
	// per-repo configurable, so this is a user-set override rather
	// than a hardcoded constant). Empty means Renovate's own
	// documented default, `rebase`.
	RenovateRebaseLabel string `json:"renovateRebaseLabel"`

	// Theme The signed-in user's own theme preference. Empty
	// means "system" — follow the browser's prefers-color-scheme
	// rather than a saved choice. Set only from Settings; every
	// other page reads it via the lightweight
	// GET /api/settings/theme instead of this endpoint.
	Theme SettingsResponseTheme `json:"theme"`

	// Timezone The signed-in user's own time zone as an IANA name such as
	// `Europe/Amsterdam`. Empty means the browser's own zone. Set only
	// from Settings (PUT /api/settings/timezone); every other page reads
	// it via GET /api/settings/timezone.
	Timezone *string `json:"timezone,omitempty"`

	// WebhookSecret Pasted into the forge's own webhook "Secret" field, used to
	// verify the signature header on incoming webhook deliveries
	// (`X-Hub-Signature-256` on GitHub, `X-Forgejo-Signature` on
	// Forgejo). Never appears in the webhook URL itself.
	WebhookSecret string `json:"webhookSecret"`

	// WebhookToken Identifies this user in a webhook URL
	// (`/api/webhooks/{provider}/{webhookToken}`). Generated on
	// first visit to Settings and stable after that.
	WebhookToken string `json:"webhookToken"`
}

// SettingsResponseTheme The signed-in user's own theme preference. Empty
// means "system" — follow the browser's prefers-color-scheme
// rather than a saved choice. Set only from Settings; every
// other page reads it via the lightweight
// GET /api/settings/theme instead of this endpoint.
type SettingsResponseTheme string

